/*
 * Cloudflare Worker entry. Wraps the OpenNext handler (unchanged) and adds the
 * auction's live channel and Durable Object.
 *
 * - GET /api/auction/live (WebSocket) → AuctionRoom. Read-only: screens receive
 *   state; every change goes through authenticated HTTPS routes in the Next app.
 * - Everything else → OpenNext, exactly as before.
 */
// @ts-expect-error -- generated by `opennextjs-cloudflare build`; exists only after a build.
import openNext from "./.open-next/worker.js";
import { AUCTION_ROOM_NAME, type AuctionEnv } from "./src/auction/cf";

// OpenNext's own Durable Objects must stay exported from the entry module.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
export { AuctionRoom } from "./src/auction/room";

type Handler = { fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> };

const worker = {
  async fetch(request: Request, env: AuctionEnv, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname === "/api/auction/live") {
      if (request.method !== "GET" || request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
        return new Response("Expected a WebSocket upgrade", { status: 426 });
      }
      // Browsers always send Origin on WebSocket requests; only accept our own site.
      const origin = request.headers.get("Origin");
      if (origin && new URL(origin).host !== url.host) return new Response("Forbidden", { status: 403 });
      const room = env.AUCTION_ROOM.get(env.AUCTION_ROOM.idFromName(AUCTION_ROOM_NAME));
      return room.fetch(new Request("https://auction-room/live", request));
    }
    return (openNext as Handler).fetch(request, env, ctx);
  },
};

export default worker;
